public List<Message> loadAll(long campaignId) {
    List<Message> all = new ArrayList<>();
    ResultSet rs = stmt.executeQuery(
        "SELECT * FROM messages WHERE campaign_id = " + campaignId);
    while (rs.next()) all.add(map(rs));
    return all;
